   const on=!!S.extraTip&&!S.extrasDone&&!$("#extrasBlock").hidden;tip.hidden=!on;if(on)tip.innerHTML=`<span aria-hidden="true">👇</span><span>Add something extra, or tap <b>No extras, thanks</b> to continue.</span>`;
