  if(c.go!=="needcourier"){const m=$("#ctaMsg");if(m)m.hidden=true}
  $("#clearBtn").disabled=!boxN();
  $("#randBtn").disabled=!availProducts().length;
  $("#randLabel").textContent=full()?"Shuffle box":"Random fill";
  pop.clear();
