    const bad=failed&&i===endI,done=!bad&&(i<idx||(o.status==="completed"&&i===endI)||(!!cp&&i===cpI&&cpDone)),now=!bad&&!done&&(i===idx||(!!cp&&i===cpI)),srch=!!b&&i===4&&!!cs.srch&&now;
