  {const nc=DB.coupons.filter(c=>!c.aff&&cpState(c)==="live").length;$("#cCoupons").textContent=nc?nc+" live":"";$("#cCoupons").hidden=!nc;$("#cCoupons").classList.toggle("live",!!nc)}
  $("#cSales").textContent=nLive?nLive+" live":"";$("#cSales").hidden=!nLive;
