  const img=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(new Error("Couldn't read that SVG. Try a PNG."));i.src="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(t)});
