    const used=new Set(D.rules.filter(r=>!r.custom).map(r=>+r.from)),free=DB.sizes.map(z=>z.n).sort((a,b)=>a-b).find(n=>!used.has(n)),cm=DB.settings;
    if(free)D.rules.push({id:uid(),from:free,to:free,limit:1,mode:"specific",ids:[]});
